  if (!sd) return { sd: null, mapa: {} };
  const valido = sd.rroca && typeof sd.rroca === 'object' && !Array.isArray(sd.rroca);
  if (!valido) {
    if (escribir !== true) return { sd: sd, mapa: {} };
    sd.rroca = {};
  }
  return { sd: sd, mapa: sd.rroca };
}
